/* Auto-generated from imu_dashboard.html. Do not edit manually. */
static const char IMU_DASHBOARD_HTML[] = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>IMU 实时监测</title>\n<style>\nbody { margin: 0; background: #0b0f14; color: #e8f0f8; font-family: Arial, sans-serif; }\nheader { padding: 12px 16px; background: #151b23; border-bottom: 1px solid #26313d; }\nh1 { margin: 0; font-size: 18px; }\nmain { padding: 16px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; max-width: 640px; margin: 0 auto; }\n.card { background: #151b23; border-radius: 10px; padding: 14px; text-align: center; border: 1px solid #26313d; }\n.value { font-size: 32px; font-weight: bold; color: #4fc3f7; }\n.label { font-size: 12px; color: #8fa4b8; margin-top: 4px; }\n#turn { grid-column: 1 / -1; }\n#turn-state { font-size: 22px; font-weight: bold; margin: 6px 0; min-height: 30px; }\n.arrow { width: 80px; height: 80px; margin: 8px auto; transition: transform 0.05s linear; }\n.arrow svg { fill: #4fc3f7; }\n#chart { grid-column: 1 / -1; width: 100%; height: 180px; background: #0f141a; border-radius: 10px; border: 1px solid #26313d; }\n#ctrl { grid-column: 1 / -1; display: flex; gap: 8px; justify-content: center; align-items: center; flex-wrap: wrap; }\nbutton { background: #26313d; color: #e8f0f8; border: none; padding: 6px 12px; border-radius: 6px; cursor: pointer; }\nbutton.active { background: #4fc3f7; color: #000; }\n</style>\n</head>\n<body>\n<header><h1>IMU 实时监测</h1></header>\n<main>\n<div class=\"card\"><div class=\"value\" id=\"roll\">--</div><div class=\"label\">Roll (°)</div></div>\n<div class=\"card\"><div class=\"value\" id=\"pitch\">--</div><div class=\"label\">Pitch (°)</div></div>\n<div class=\"card\"><div class=\"value\" id=\"yaw\">--</div><div class=\"label\">Yaw (°)</div></div>\n<div class=\"card\" id=\"turn\">\n  <div class=\"label\">转向状态</div>\n  <div id=\"turn-state\">等待数据...</div>\n  <div class=\"arrow\" id=\"arrow\"><svg viewBox=\"0 0 100 100\"><polygon points=\"50,10 80,80 50,65 20,80\"/></svg></div>\n  <div class=\"label\">完成次数: <span id=\"turn-count\">0</span> | 上次角度: <span id=\"turn-last\">0</span>°</div>\n</div>\n<canvas id=\"chart\"></canvas>\n<div id=\"ctrl\">\n  <span class=\"label\">轮询间隔:</span>\n  <button data-ms=\"50\">50ms</button>\n  <button data-ms=\"100\" class=\"active\">100ms</button>\n  <button data-ms=\"200\">200ms</button>\n</div>\n</main>\n<script>\nconst $ = id => document.getElementById(id);\nconst rollEl = $('roll'), pitchEl = $('pitch'), yawEl = $('yaw'), stateEl = $('turn-state');\nconst arrowEl = $('arrow'), countEl = $('turn-count'), lastEl = $('turn-last');\nconst canvas = $('chart'), ctx = canvas.getContext('2d');\nlet interval = 100, history = [], maxPoints = 120, lastYaw = null, unwrap = 0;\nfunction resize() {\n  canvas.width = canvas.clientWidth * window.devicePixelRatio;\n  canvas.height = canvas.clientHeight * window.devicePixelRatio;\n  ctx.setTransform(window.devicePixelRatio, 0, 0, window.devicePixelRatio, 0, 0);\n}\nwindow.addEventListener('resize', resize); resize();\ndocument.querySelectorAll('#ctrl button').forEach(b => b.onclick = () => {\n  document.querySelectorAll('#ctrl button').forEach(x => x.classList.remove('active'));\n  b.classList.add('active'); interval = +b.dataset.ms;\n});\nfunction update(d) {\n  const a = d.attitude, t = d.turn || {};\n  rollEl.textContent = a.roll.toFixed(1);\n  pitchEl.textContent = a.pitch.toFixed(1);\n  yawEl.textContent = a.yaw.toFixed(1);\n  let txt = t.state || 'idle';\n  if (t.in_progress) txt = '转向中: ' + (t.dir || '');\n  stateEl.textContent = txt;\n  countEl.textContent = t.completed_count || 0;\n  lastEl.textContent = (t.last_completed_deg || 0).toFixed(1);\n  let y = a.yaw;\n  if (lastYaw !== null) {\n    let dy = y - lastYaw;\n    while (dy > 180) dy -= 360;\n    while (dy < -180) dy += 360;\n    unwrap += dy;\n  } else { unwrap = y; }\n  lastYaw = y;\n  arrowEl.style.transform = 'rotate(' + y + 'deg)';\n  history.push(unwrap);\n  if (history.length > maxPoints) history.shift();\n  draw();\n}\nfunction draw() {\n  const w = canvas.clientWidth, h = canvas.clientHeight;\n  ctx.clearRect(0, 0, w, h);\n  if (history.length < 2) return;\n  let min = Math.min(...history), max = Math.max(...history);\n  if (max - min < 20) { let c = (max + min) / 2; min = c - 10; max = c + 10; }\n  ctx.strokeStyle = '#4fc3f7'; ctx.lineWidth = 2; ctx.beginPath();\n  history.forEach((v, i) => {\n    const x = i / (maxPoints - 1) * w;\n    const y = h - ((v - min) / (max - min)) * h * 0.8 - h * 0.1;\n    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);\n  });\n  ctx.stroke();\n  ctx.fillStyle = '#8fa4b8'; ctx.font = '12px Arial';\n  ctx.fillText(min.toFixed(1) + '°', 4, h - 4);\n  ctx.fillText(max.toFixed(1) + '°', 4, 12);\n}\nasync function poll() {\n  try {\n    const r = await fetch('/imu?t=' + Date.now(), { cache: 'no-store' });\n    const d = await r.json();\n    if (!d.error) update(d);\n  } catch (e) { stateEl.textContent = '连接失败'; }\n  setTimeout(poll, interval);\n}\npoll();\n</script>\n</body>\n</html>\n";
